import{_ as o,l as r,o as a,c as s,v as t,p as n,x as l,d,i as c,S as p}from"./chunks/framework.InCnrqk-.js";const f=JSON.parse('{"title":"协作调度","description":"","frontmatter":{"title":"协作调度","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/cooperative-scheduling.md","filePath":"cs/cooperative-scheduling.md","lastUpdated":1789023840000}'),h={name:"cs/cooperative-scheduling.md"};function u(E,e,m,_,B,A){const i=r("Mermaid");return a(),s("div",null,[e[1]||(e[1]=t('<h1 id="协作调度" tabindex="-1">协作调度 <a class="header-anchor" href="#协作调度" aria-label="Permalink to &quot;协作调度&quot;">​</a></h1><div class="epigraph"><p>协作调度只在任务自愿 yield 时换人：无时钟中断抢占，临界区简单，失控循环能饿死全机。</p><footer>—— 据 Tanenbaum 对协作与抢占的对照；早期 Mac/Windows 与嵌入式 run-to-completion 实践</footer></div><p><a href="/cs/user-level-scheduling">M:N</a> 的纤维切换常是协作的。<a href="/cs/preempt-rt">PREEMPT_RT</a> 走另一极端。缺口是 <strong>协作作为一等模型</strong>：内核或用户，何时还用。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>抢占需要保存完整上下文、处理抢占点。协作：<code>yield</code>/<code>await</code> 才换。缺口：Linux 用户态可 <code>sched_yield</code>，但不保证别人跑；内核历史上 <code>CONFIG_PREEMPT</code> 关闭则系统调用内协作。本课不把协程语法写成语言课。</p><p><span class="marginnote">run-to-completion 在网卡 NAPI 配额里也有影子：poll 跑到 weight。对象是调度哲学。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>任务跑直到阻塞或 yield。对照 EEVDF：时钟抢占切时间片。对照 <a href="/cs/fuse">FUSE</a>：守护必须自己不在回调里死循环。对照 DL：硬时限不能指望协作。</p>',8)),(a(),n(p,null,{default:l(()=>[c(i,{id:"mermaid-22",class:"mermaid",graph:"flowchart%20TD%0A%20%20T%5B%22%E4%BB%BB%E5%8A%A1%E8%BF%90%E8%A1%8C%22%5D%20--%3E%20Y%5B%22yield%20%E6%88%96%E9%98%BB%E5%A1%9E%22%5D%0A%20%20Y%20--%3E%20N%5B%22%E4%B8%8B%E4%B8%80%E4%B8%AA%E5%B0%B1%E7%BB%AA%22%5D%0A%20%20SPIN%5B%22%E6%97%A0%20yield%20%E6%AD%BB%E5%BE%AA%E7%8E%AF%22%5D%20--%3E%20STARVE%5B%22%E9%A5%BF%E6%AD%BB%22%5D%0A"})]),fallback:l(()=>[...e[0]||(e[0]=[d(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=t('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>协作把正确性（无意外抢占）换饥饿风险，适合可信短任务与教学。现代通用 OS 默认抢占，协作留在用户运行时内部。不要写成倒退推荐。与 <a href="/cs/latency-measurement">cyclictest</a>：协作内核的 max 延迟可以是「一个长 syscall」。</p><p>混合：抢占内核 + 用户协作纤维是常见。</p><p>实现上：内核 CONFIG_PREEMPT=n 时，长系统调用等于不可抢占段。用户态协作适合可信短任务。混合模型：内核抢占线程，线程内协作纤维。 读法上只引用<a href="/cs/user-level-scheduling">上一课</a>的结论，不把对象换成训练推理或限价簿。</p><p>本课在操作系统进阶的「调度进阶 / 公平、实时与能耗」课序里，对象是 <strong>协作调度</strong>。</p><ul><li>先修只引用，不重导：上一课的结论当公理，本课只补差。</li><li>五栏不吞并：不把本课写成大模型训练/推理，也不写成限价簿或权重量化。</li><li>文献用 OSTEP、McKusick、内核文档与具名会议论文；不发明 arXiv 编号。</li></ul><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不引入 Ada 会合的全部。不保证实时协作语言的 WCET 工具。下一课如何评价「公平」：度量。</p><p>版本字段会变，课序钉的是机制对象「协作调度」，不是某一主线内核的结构体名。 后课默认：无自愿让出则协作模型可饿死。公平性指标，下一课。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>协作：只在 yield/阻塞时切换。</li><li>实现简单，失控即饥饿。</li><li>公平性度量是下一课。</li><li>出处：Tanenbaum <em>MOS</em>；<em>OSTEP</em> 调度；历史桌面 OS。</li></ul>',11))])}const P=o(h,[["render",u]]);export{f as __pageData,P as default};
